import JSZip from 'jszip';

const WORKSHEET_PATH = /(?:^|\/)worksheets\/[^/]+\.xml$/i;
const SHEET_DATA_OPEN = /<(?:[A-Za-z_][\w.-]*:)?sheetData(?=[\s/>])/g;
const SHEET_DATA_CLOSE = /<\/(?:[A-Za-z_][\w.-]*:)?sheetData>/g;
const ROW_OPEN = /<(?:[A-Za-z_][\w.-]*:)?row(?=[\s/>])/g;
const ROW_CLOSE = /<\/(?:[A-Za-z_][\w.-]*:)?row>/g;

/**
 * Drops worksheet rows the preview will not show, so the parser never builds them.
 * An `.xlsx` is compressed XML: a 10 MB file can hold far more rows than the browser should materialize.
 */
export async function capWorkbookForPreview(blob: Blob, maxRows: number): Promise<Blob> {
	const zip = await JSZip.loadAsync(blob);
	const worksheets = Object.values(zip.files).filter((file) => !file.dir && WORKSHEET_PATH.test(file.name));
	let changed = false;

	for (const file of worksheets) {
		const capped = capWorksheetXml(await file.async('string'), maxRows);
		if (capped.truncated) {
			zip.file(file.name, capped.xml);
			changed = true;
		}
	}

	if (!changed) {
		return blob;
	}

	return zip.generateAsync({ type: 'blob', compression: 'STORE' });
}

export function capWorksheetXml(xml: string, maxRows: number): { xml: string; truncated: boolean } {
	SHEET_DATA_OPEN.lastIndex = 0;
	const sheetOpen = SHEET_DATA_OPEN.exec(xml);
	if (!sheetOpen) {
		return { xml, truncated: false };
	}

	const openEnd = xml.indexOf('>', sheetOpen.index);
	if (openEnd === -1 || xml[openEnd - 1] === '/') {
		return { xml, truncated: false };
	}

	SHEET_DATA_CLOSE.lastIndex = openEnd;
	const sheetClose = SHEET_DATA_CLOSE.exec(xml);
	if (!sheetClose) {
		return { xml, truncated: false };
	}

	if (maxRows <= 0) {
		if (!hasRow(xml, openEnd + 1, sheetClose.index)) {
			return { xml, truncated: false };
		}
		return { xml: xml.slice(0, openEnd + 1) + xml.slice(sheetClose.index), truncated: true };
	}

	ROW_OPEN.lastIndex = openEnd;
	let rows = 0;
	let lastRowEnd = openEnd + 1;

	while (rows < maxRows) {
		const row = ROW_OPEN.exec(xml);
		if (!row || row.index >= sheetClose.index) {
			return { xml, truncated: false };
		}

		const rowEnd = endOfRow(xml, row.index);
		if (rowEnd === -1 || rowEnd > sheetClose.index) {
			return { xml, truncated: false };
		}

		lastRowEnd = rowEnd;
		ROW_OPEN.lastIndex = rowEnd;
		rows += 1;
	}

	const extra = ROW_OPEN.exec(xml);
	if (!extra || extra.index >= sheetClose.index) {
		return { xml, truncated: false };
	}

	return { xml: xml.slice(0, lastRowEnd) + xml.slice(sheetClose.index), truncated: true };
}

function hasRow(xml: string, from: number, until: number): boolean {
	ROW_OPEN.lastIndex = from;
	const row = ROW_OPEN.exec(xml);
	return row !== null && row.index < until;
}

function endOfRow(xml: string, start: number): number {
	const tagEnd = xml.indexOf('>', start);
	if (tagEnd === -1) {
		return -1;
	}
	if (xml[tagEnd - 1] === '/') {
		return tagEnd + 1;
	}

	ROW_CLOSE.lastIndex = tagEnd + 1;
	const close = ROW_CLOSE.exec(xml);
	return close ? close.index + close[0].length : -1;
}

import { describe, expect, it } from 'vitest';
import writeXlsxFile from 'write-excel-file/universal';

import { capWorkbookForPreview, capWorksheetXml } from './workbook-preview';

describe('capWorksheetXml', () => {
	it('keeps a sheet that is already within the row budget', () => {
		const xml = worksheetXml(rowsXml(2));
		expect(capWorksheetXml(xml, 2)).toEqual({ xml, truncated: false });
		expect(capWorksheetXml(xml, 5)).toEqual({ xml, truncated: false });
	});

	it('drops rows beyond the budget and closes the sheet', () => {
		const { xml, truncated } = capWorksheetXml(worksheetXml(rowsXml(4)), 2);

		expect(truncated).toBe(true);
		expect(xml).toBe(worksheetXml(rowsXml(2)));
		expect(xml.match(/<row /g)).toHaveLength(2);
		expect(xml).toContain('</sheetData>');
		expect(xml).toContain('</worksheet>');
	});

	it('counts self-closing rows', () => {
		const xml = worksheetXml('<row r="1"/><row r="2"/><row r="3"/>');
		const capped = capWorksheetXml(xml, 2);

		expect(capped.truncated).toBe(true);
		expect(capped.xml).toBe(worksheetXml('<row r="1"/><row r="2"/>'));
	});

	it('does not treat rowBreaks as sheet rows', () => {
		const xml = `<?xml version="1.0"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${rowsXml(1)}</sheetData><rowBreaks count="1"><brk id="1"/></rowBreaks></worksheet>`;

		expect(capWorksheetXml(xml, 1)).toEqual({ xml, truncated: false });
	});

	it('leaves a sheet with no rows unchanged', () => {
		const xml = worksheetXml('');
		expect(capWorksheetXml(xml, 3)).toEqual({ xml, truncated: false });
		expect(capWorksheetXml(worksheetXmlEmptySelfClosing(), 3)).toEqual({
			xml: worksheetXmlEmptySelfClosing(),
			truncated: false,
		});
	});
});

describe('capWorkbookForPreview', () => {
	it('stops workbook parsing at the row budget', async () => {
		const blob = await writeXlsxFile(
			Array.from({ length: 8 }, (_, index) => [{ type: String, value: `r${index}` }]),
		).toBlob();

		const { default: readXlsxFile } = await import('read-excel-file/browser');
		const sheets = await readXlsxFile(await capWorkbookForPreview(blob, 3));

		expect(sheets).toHaveLength(1);
		expect(sheets[0]?.data).toEqual([['r0'], ['r1'], ['r2']]);
	});

	it('does not rewrite a workbook that already fits', async () => {
		const blob = await writeXlsxFile([[{ type: String, value: 'only' }]]).toBlob();

		await expect(capWorkbookForPreview(blob, 3)).resolves.toBe(blob);
	});
});

const rowsXml = (count: number): string => {
	return Array.from({ length: count }, (_, index) => {
		const row = index + 1;
		return `<row r="${row}"><c r="A${row}" t="inlineStr"><is><t>r${index}</t></is></c></row>`;
	}).join('');
};

const worksheetXml = (rows: string): string => {
	return `<?xml version="1.0"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${rows}</sheetData></worksheet>`;
};

const worksheetXmlEmptySelfClosing = (): string => {
	return `<?xml version="1.0"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData/></worksheet>`;
};

